// Einstellungen dieses Workflows – nach dem Import hier eintragen (Anleitung: docs/n8n/EUROFLEX-MAILEINGANG.md).
// POSTFACH: Adresse des gemeinsamen Eingangspostfachs in Outlook 365. Teil des Schlüssels im Portal (Postfach + Message-ID) –
// später nicht mehr ändern, sonst gelten bekannte Mails als neu.
const POSTFACH = '';
// QUELLORDNER: aus diesem Ordner werden die ungelesenen Mails geholt – bekannter Name (Inbox) oder Ordner-ID aus Microsoft Graph.
const QUELLORDNER = 'Inbox';
// ZIELWURZEL: unter diesem Ordner liegen die Zielordner aus der Antwort des Portals (z. B. „Portal/Zugeordnet“); fehlende werden angelegt.
const ZIELWURZEL = 'Inbox';
// MAX: höchstens so viele Mails je Lauf; der Rest folgt im nächsten Lauf.
const MAX = 50;

const postfach = String(POSTFACH).trim();
if (!/^[^\s@<>]+@[^\s@<>]+\.[^\s@<>]+$/.test(postfach)) {
  throw new Error('Knoten „Konfiguration“: unter POSTFACH die Adresse des Eingangspostfachs eintragen.');
}
return [{ json: {
  postfach,
  quellordner: String(QUELLORDNER).trim() || 'Inbox',
  zielwurzel: String(ZIELWURZEL).trim() || 'Inbox',
  max: Math.max(1, Math.min(Number(MAX) || 50, 200)),
} }];

// Antwort von „Mails lesen“ prüfen und je ungelesener Mail ein Element bilden.
// Scheitert das Lesen, bricht der Lauf mit einer verständlichen Meldung ab (sichtbar unter Executions).
const k = $('Konfiguration').first().json;
const a = $input.first().json;
/** Klartext für eine Ablehnung durch Microsoft Graph */
function graphFehler(a, schritt) {
  const s = a.statusCode;
  const e = a.body && typeof a.body === 'object' ? a.body.error : null;
  const roh = e ? `${e.code ?? ''}: ${e.message ?? ''}`.replace(/^: /, '') : String((a.error && (a.error.message || a.error)) || (typeof a.body === 'string' ? a.body : '') || 'keine Antwort').slice(0, 300);
  let hinweis = '';
  if (s === 401) hinweis = ' Die Zugangsdatei „Euroflex Microsoft Graph“ in n8n ist ungültig oder der Clientschlüssel abgelaufen.';
  else if (s === 403) hinweis = ' Die App darf dieses Postfach nicht lesen oder ändern (Berechtigung Mail.ReadWrite bzw. Bereich in Exchange prüfen).';
  else if (s === 404) hinweis = ' Postfach oder Ordner gibt es in Microsoft 365 nicht (Knoten „Konfiguration“ prüfen).';
  return `${schritt} fehlgeschlagen${s ? ` (HTTP ${s})` : ''}: ${roh}${hinweis}`;
}
if (a.statusCode !== 200 || !a.body || typeof a.body !== 'object' || !Array.isArray(a.body.value)) {
  throw new Error(graphFehler(a, `Mails lesen aus ${k.postfach}/${k.quellordner}`));
}
return a.body.value.filter((m) => m && m.id).map((m, i) => ({
  json: { postfach: k.postfach, graph_id: m.id, betreff: String(m.subject ?? ''), mail: m },
  pairedItem: { item: 0 },
}));

// Je Mail die Lieferung an das Portal bauen – Aufbau laut docs/euroflex-mailworkflows.md, Abschnitt „Schnittstelle für n8n“.
// Eingang: Antworten von „Anhänge laden“ in derselben Reihenfolge wie „Mails aufteilen“.
// Nur Dateianhänge (#microsoft.graph.fileAttachment); contentBytes ist bereits Base64. Angehängte E-Mails (itemAttachment)
// und Verweise (referenceAttachment) werden nicht geliefert. Signaturbilder, .ics, .vcf, .p7s filtert das Portal.
const mails = $('Mails aufteilen').all();
const antworten = $input.all();
const MAX_ANHAENGE = 40;
const MAX_BASE64 = 78 * 1024 * 1024; // Portal nimmt höchstens 80 MB je Anfrage an
/** Klartext für eine Ablehnung durch Microsoft Graph */
function graphFehler(a, schritt) {
  const s = a.statusCode;
  const e = a.body && typeof a.body === 'object' ? a.body.error : null;
  const roh = e ? `${e.code ?? ''}: ${e.message ?? ''}`.replace(/^: /, '') : String((a.error && (a.error.message || a.error)) || (typeof a.body === 'string' ? a.body : '') || 'keine Antwort').slice(0, 300);
  let hinweis = '';
  if (s === 401) hinweis = ' Die Zugangsdatei „Euroflex Microsoft Graph“ in n8n ist ungültig oder der Clientschlüssel abgelaufen.';
  else if (s === 403) hinweis = ' Die App darf dieses Postfach nicht lesen oder ändern (Berechtigung Mail.ReadWrite bzw. Bereich in Exchange prüfen).';
  else if (s === 404) hinweis = ' Postfach oder Ordner gibt es in Microsoft 365 nicht (Knoten „Konfiguration“ prüfen).';
  return `${schritt} fehlgeschlagen${s ? ` (HTTP ${s})` : ''}: ${roh}${hinweis}`;
}

/** HTML grob in lesbaren Text umwandeln (für Zuordnung und Anzeige; das Original geht als html mit) */
function htmlZuText(html) {
  const zeichen = { nbsp: ' ', amp: '&', lt: '<', gt: '>', quot: '"', apos: "'", auml: 'ä', ouml: 'ö', uuml: 'ü', Auml: 'Ä', Ouml: 'Ö', Uuml: 'Ü', szlig: 'ß', euro: '€' };
  return String(html)
    .replace(/<!--[\s\S]*?-->/g, '')
    .replace(/<(head|style|script|title)\b[\s\S]*?<\/\1\s*>/gi, '')
    .replace(/<br\s*\/?>/gi, '\n')
    .replace(/<\/(p|div|tr|li|h[1-6]|table|blockquote)\s*>/gi, '\n')
    .replace(/<(td|th)\b[^>]*>/gi, ' ')
    .replace(/<[^>]+>/g, '')
    .replace(/&#x([0-9a-f]+);/gi, (_, h) => String.fromCodePoint(parseInt(h, 16)))
    .replace(/&#(\d+);/g, (_, d) => String.fromCodePoint(Number(d)))
    .replace(/&([a-z]+);/gi, (m, n) => (n in zeichen ? zeichen[n] : m))
    .replace(/[ \t ]+/g, ' ')
    .replace(/ *\n */g, '\n')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}
/** Graph-Empfänger → „Name <adresse>“ bzw. „adresse“ */
function adresse(r) {
  const e = (r && r.emailAddress) || {};
  const addr = String(e.address ?? '').trim();
  const name = String(e.name ?? '').replace(/[<>"]/g, '').trim();
  if (!addr) return name;
  return name && name.toLowerCase() !== addr.toLowerCase() ? `${name} <${addr}>` : addr;
}
/** Kopfzeile aus internetMessageHeaders (Name ohne Beachtung der Groß-/Kleinschreibung) */
function kopf(liste, name) {
  const h = (Array.isArray(liste) ? liste : []).find((x) => String(x?.name ?? '').toLowerCase() === name);
  return h ? String(h.value ?? '').replace(/\s+/g, ' ').trim() : '';
}

return mails.map((it, i) => {
  const m = it.json.mail || {};
  const a = (antworten[i] && antworten[i].json) || {};
  const basis = { postfach: it.json.postfach, graph_id: it.json.graph_id, betreff: String(m.subject ?? '') };
  if (a.statusCode !== 200 || !a.body || typeof a.body !== 'object' || !Array.isArray(a.body.value)) {
    return { json: { ...basis, ok: false, fehler: graphFehler(a, 'Anhänge laden'), payload: null }, pairedItem: { item: i } };
  }
  const anhaenge = a.body.value
    .filter((x) => x && x['@odata.type'] === '#microsoft.graph.fileAttachment' && x.contentBytes)
    .map((x) => ({
      name: String(x.name ?? '').trim() || 'Anhang',
      mime: String(x.contentType ?? '').trim() || 'application/octet-stream',
      inhalt: String(x.contentBytes).replace(/\s+/g, ''),
    }));
  const fehler = [];
  if (anhaenge.length > MAX_ANHAENGE) fehler.push(`${anhaenge.length} Anhänge – das Portal nimmt höchstens ${MAX_ANHAENGE} je Mail an.`);
  const groesse = anhaenge.reduce((s, x) => s + x.inhalt.length, 0);
  if (groesse > MAX_BASE64) fehler.push(`Anhänge zu groß (${Math.round(groesse * 3 / 4 / 1048576)} MB) – das Portal nimmt höchstens 80 MB je Mail an.`);

  const body = m.body || {};
  const istHtml = String(body.contentType ?? '').toLowerCase() === 'html';
  const inhalt = String(body.content ?? '');
  const h = m.internetMessageHeaders;
  const payload = {
    postfach: it.json.postfach,
    graph_id: it.json.graph_id,
    message_id: String(m.internetMessageId ?? '').trim() || `<${it.json.graph_id}@graph.microsoft.com>`,
    in_reply_to: kopf(h, 'in-reply-to'),
    references: kopf(h, 'references'),
    von: adresse(m.from || m.sender),
    an: (Array.isArray(m.toRecipients) ? m.toRecipients : []).map(adresse).filter(Boolean).join(', '),
    betreff: String(m.subject ?? ''),
    datum: String(m.receivedDateTime ?? ''),
    text: istHtml ? htmlZuText(inhalt) : inhalt,
    ...(istHtml ? { html: inhalt } : {}),
    anhaenge,
  };
  return { json: { ...basis, ok: !fehler.length, fehler: fehler.join(' '), payload: fehler.length ? null : payload }, pairedItem: { item: i } };
});

// Antworten des Portals auswerten (einmal für alle Mails). Ergebnis ist genau EIN Element mit dem Stand für die Ordnersuche:
// verschoben wird nur, wo das Portal mit aktion.ordner antwortet. Mails ohne gültige Antwort bleiben ungelesen im Postfach
// und kommen im nächsten Lauf erneut (das Portal erkennt schon verarbeitete Mails und antwortet „doppelt“ mit aktion).
const k = $('Konfiguration').first().json;
const gepackt = $('Lieferbar?').all();

/** „ Portal \\ Zugeordnet/ “ → „Portal/Zugeordnet“ */
const pfadNorm = (p) => String(p ?? '').split(/[\/\\]/).map((t) => t.trim()).filter(Boolean).join('/');
function portalFehler(a) {
  const s = a.statusCode;
  const b = a.body;
  const roh = b && typeof b === 'object' ? String(b.message ?? b.fehler ?? b.error ?? JSON.stringify(b)) : String((a.error && (a.error.message || a.error)) || b || 'keine Antwort');
  let hinweis = '';
  if (s === 401) hinweis = ' API-Schlüssel fehlt, ist gesperrt oder abgelaufen (Zugangsdatei „Euroflex Portal API-Schlüssel“).';
  else if (s === 403) hinweis = ' Schlüssel ohne Recht transport.eingang:execute oder Funktion „E-Mail-Eingang über n8n“ ausgeschaltet.';
  else if (s === 404) hinweis = ' Adresse des Portals falsch oder Modul transport nicht aktiv.';
  else if (s === 413) hinweis = ' Mail zu groß für das Portal.';
  return `Portal (HTTP ${s ?? '–'}): ${roh.slice(0, 300)}${hinweis}`;
}

const ergebnisse = $input.all().map((it, i) => {
  const a = it.json || {};
  const p = (gepackt[i] && gepackt[i].json) || {};
  const ok = a.statusCode >= 200 && a.statusCode < 300 && a.body && typeof a.body === 'object';
  const b = ok ? a.body : {};
  const ordner = ok && b.aktion && typeof b.aktion === 'object' ? pfadNorm(b.aktion.ordner) : '';
  return {
    graph_id: p.graph_id, betreff: p.betreff, http: a.statusCode ?? null,
    vorgang: b.vorgang ?? null, status: b.status ?? null, auftragsnr: b.auftragsnr ?? null, ordner,
    fehler: ok ? '' : portalFehler(a),
  };
});
if (ergebnisse.length && ergebnisse.every((e) => e.fehler)) {
  throw new Error(`Keine Mail an das Portal geliefert – alle bleiben ungelesen im Postfach. ${ergebnisse[0].fehler}`);
}
const verschieben = ergebnisse.filter((e) => e.ordner).map((e) => ({ graph_id: e.graph_id, pfad: e.ordner }));
return [{ json: {
  postfach: k.postfach, wurzel: k.zielwurzel, ergebnisse, verschieben,
  offen: [...new Set(verschieben.map((v) => v.pfad))], ordner: {}, angelegt: [], fehler: {}, schritte: 0, schritt: null, anlegen: false,
} }];

// Zielordner Ebene für Ebene auflösen (Schleife: Ordner planen → Ordner suchen → ggf. Ordner anlegen → zurück hierher).
// Je Durchlauf genau ein Schritt; „schritt“ = nächste fehlende Ebene, null = alle Pfade aufgelöst oder als Fehler vermerkt.
const s = JSON.parse(JSON.stringify($input.first().json));
s.schritt = null;
s.anlegen = false;
while (s.offen.length) {
  const pfad = s.offen[0];
  const teile = pfad.split('/');
  let eltern = s.wurzel;
  for (let e = 0; e < teile.length && !s.schritt; e++) {
    const praefix = teile.slice(0, e + 1).join('/');
    if (s.ordner[praefix]) eltern = s.ordner[praefix];
    else s.schritt = { pfad, praefix, name: teile[e], eltern };
  }
  if (s.schritt) break;
  s.offen.shift();
}
// Sicherung gegen eine Endlosschleife: höchstens 30 Graph-Schritte je Lauf
if (s.schritt && s.schritte >= 30) {
  for (const p of s.offen) s.fehler[p] = 'Ordner nicht aufgelöst: zu viele Schritte in einem Lauf.';
  s.offen = [];
  s.schritt = null;
}
return [{ json: s }];

// Ergebnis von „Ordner suchen“: gefunden → ID merken; nicht vorhanden → anlegen; Fehler → Pfad aufgeben (Mails bleiben ungelesen).
const s = JSON.parse(JSON.stringify($('Ordner planen').first().json));
const a = $input.first().json;
const st = s.schritt;
/** Klartext für eine Ablehnung durch Microsoft Graph */
function graphFehler(a, schritt) {
  const s = a.statusCode;
  const e = a.body && typeof a.body === 'object' ? a.body.error : null;
  const roh = e ? `${e.code ?? ''}: ${e.message ?? ''}`.replace(/^: /, '') : String((a.error && (a.error.message || a.error)) || (typeof a.body === 'string' ? a.body : '') || 'keine Antwort').slice(0, 300);
  let hinweis = '';
  if (s === 401) hinweis = ' Die Zugangsdatei „Euroflex Microsoft Graph“ in n8n ist ungültig oder der Clientschlüssel abgelaufen.';
  else if (s === 403) hinweis = ' Die App darf dieses Postfach nicht lesen oder ändern (Berechtigung Mail.ReadWrite bzw. Bereich in Exchange prüfen).';
  else if (s === 404) hinweis = ' Postfach oder Ordner gibt es in Microsoft 365 nicht (Knoten „Konfiguration“ prüfen).';
  return `${schritt} fehlgeschlagen${s ? ` (HTTP ${s})` : ''}: ${roh}${hinweis}`;
}
s.schritte += 1;
s.anlegen = false;
if (a.statusCode === 200 && a.body && Array.isArray(a.body.value)) {
  const f = a.body.value.find((x) => x && x.id && String(x.displayName ?? '').toLowerCase() === st.name.toLowerCase());
  if (f) s.ordner[st.praefix] = f.id;
  else s.anlegen = true;
} else {
  s.fehler[st.pfad] = graphFehler(a, `Ordner „${st.praefix}“ suchen`);
  s.offen = s.offen.filter((p) => p !== st.pfad);
}
return [{ json: s }];

// Ergebnis von „Ordner anlegen“: neue ID merken; sonst Pfad für diesen Lauf aufgeben (nächster Lauf versucht es erneut).
const s = JSON.parse(JSON.stringify($('Suche auswerten').first().json));
const a = $input.first().json;
const st = s.schritt;
/** Klartext für eine Ablehnung durch Microsoft Graph */
function graphFehler(a, schritt) {
  const s = a.statusCode;
  const e = a.body && typeof a.body === 'object' ? a.body.error : null;
  const roh = e ? `${e.code ?? ''}: ${e.message ?? ''}`.replace(/^: /, '') : String((a.error && (a.error.message || a.error)) || (typeof a.body === 'string' ? a.body : '') || 'keine Antwort').slice(0, 300);
  let hinweis = '';
  if (s === 401) hinweis = ' Die Zugangsdatei „Euroflex Microsoft Graph“ in n8n ist ungültig oder der Clientschlüssel abgelaufen.';
  else if (s === 403) hinweis = ' Die App darf dieses Postfach nicht lesen oder ändern (Berechtigung Mail.ReadWrite bzw. Bereich in Exchange prüfen).';
  else if (s === 404) hinweis = ' Postfach oder Ordner gibt es in Microsoft 365 nicht (Knoten „Konfiguration“ prüfen).';
  return `${schritt} fehlgeschlagen${s ? ` (HTTP ${s})` : ''}: ${roh}${hinweis}`;
}
s.schritte += 1;
s.anlegen = false;
if ((a.statusCode === 201 || a.statusCode === 200) && a.body && a.body.id) {
  s.ordner[st.praefix] = a.body.id;
  s.angelegt.push(st.praefix);
} else {
  s.fehler[st.pfad] = graphFehler(a, `Ordner „${st.praefix}“ anlegen`);
  s.offen = s.offen.filter((p) => p !== st.pfad);
}
return [{ json: s }];

// Je Mail mit aufgelöstem Zielordner ein Element für „Verschieben“. Mails, deren Ordner nicht aufgelöst werden konnte,
// bleiben ungelesen liegen und werden im nächsten Lauf erneut geliefert (Portal: „doppelt“) und dann verschoben.
const s = $input.first().json;
return s.verschieben
  .filter((v) => s.ordner[v.pfad])
  .map((v) => ({ json: { postfach: s.postfach, graph_id: v.graph_id, pfad: v.pfad, ziel_id: s.ordner[v.pfad] } }));

// Ergebnis von „Verschieben“ je Mail. Microsoft Graph vergibt beim Verschieben eine neue ID – „Als gelesen markieren“
// verwendet deshalb die ID aus der Antwort.
const auftraege = $('Verschieben aufteilen').all();
/** Klartext für eine Ablehnung durch Microsoft Graph */
function graphFehler(a, schritt) {
  const s = a.statusCode;
  const e = a.body && typeof a.body === 'object' ? a.body.error : null;
  const roh = e ? `${e.code ?? ''}: ${e.message ?? ''}`.replace(/^: /, '') : String((a.error && (a.error.message || a.error)) || (typeof a.body === 'string' ? a.body : '') || 'keine Antwort').slice(0, 300);
  let hinweis = '';
  if (s === 401) hinweis = ' Die Zugangsdatei „Euroflex Microsoft Graph“ in n8n ist ungültig oder der Clientschlüssel abgelaufen.';
  else if (s === 403) hinweis = ' Die App darf dieses Postfach nicht lesen oder ändern (Berechtigung Mail.ReadWrite bzw. Bereich in Exchange prüfen).';
  else if (s === 404) hinweis = ' Postfach oder Ordner gibt es in Microsoft 365 nicht (Knoten „Konfiguration“ prüfen).';
  return `${schritt} fehlgeschlagen${s ? ` (HTTP ${s})` : ''}: ${roh}${hinweis}`;
}
return $input.all().map((it, i) => {
  const a = it.json || {};
  const v = (auftraege[i] && auftraege[i].json) || {};
  const ok = (a.statusCode === 201 || a.statusCode === 200) && a.body && a.body.id;
  return { json: {
    postfach: v.postfach, graph_id: v.graph_id, pfad: v.pfad, ok: !!ok,
    neue_id: ok ? a.body.id : null, fehler: ok ? '' : graphFehler(a, `Verschieben nach „${v.pfad}“`),
  }, pairedItem: { item: i } };
});

// Zusammenfassung des Laufs (nur zur Ansicht unter Executions).
const st = $('Antwort auswerten').first().json;
const verschoben = $('Verschoben?').all();
const gelesen = $input.all();
const fehler = [];
for (const e of st.ergebnisse) if (e.fehler) fehler.push(`${e.betreff}: ${e.fehler}`);
for (const v of $('Verschiebung auswerten').all()) if (!v.json.ok) fehler.push(v.json.fehler);
gelesen.forEach((g, i) => {
  const s = g.json.statusCode;
  if (s !== 200) fehler.push(`Als gelesen markieren (HTTP ${s ?? '–'}): ${verschoben[i] ? verschoben[i].json.pfad : ''}`);
});
return [{ json: {
  geliefert: st.ergebnisse.filter((e) => !e.fehler).length,
  verschoben: verschoben.length,
  als_gelesen: gelesen.filter((g) => g.json.statusCode === 200).length,
  status: st.ergebnisse.reduce((m, e) => { if (e.status) m[e.status] = (m[e.status] ?? 0) + 1; return m; }, {}),
  fehler,
} }];
